import {useRef, useState} from 'react'
import {ActionMenu, ActionList, RelativeTime, Truncate, IconButton} from '@primer/react'
import {agoString} from '@github-ui/ago'
import {ListItem} from '@github-ui/list-view/ListItem'
import {ListItemDescription} from '@github-ui/list-view/ListItemDescription'
import {ListItemMainContent} from '@github-ui/list-view/ListItemMainContent'
import {ListItemTitle} from '@github-ui/list-view/ListItemTitle'
import {ListItemMetadata} from '@github-ui/list-view/ListItemMetadata'
import {ListItemTrailingBadge} from '@github-ui/list-view/ListItemTrailingBadge'
import {KebabHorizontalIcon, TrashIcon} from '@primer/octicons-react'
import {ImageSource, type ImageVersion, ImageVersionState} from '@github-ui/github-hosted-runners-settings/types/image'
import {DeleteCustomImageVersionDialog} from './DeleteCustomImageVersionDialog'
import {ImageStateIndicator} from './ImageStateIndicator'
import {useFeatureFlag} from '@github-ui/react-core/use-feature-flag'
import styles from './CustomImageVersionItem.module.css'

interface Props {
  entityLogin: string
  imageDefinitionId: string
  isEnterprise: boolean
  isLatest: boolean
  version: ImageVersion
  canWriteCustomImages: boolean
}

export default function CustomImageVersionItem(props: Props) {
  const {entityLogin, imageDefinitionId, isEnterprise, isLatest, version} = props
  const [deleteDialogIsOpen, setDeleteDialogIsOpen] = useState(false)
  const [imageVersionState, setImageVersionState] = useState<ImageVersionState | null>(version.state)
  const contextMenuButtonRef = useRef<HTMLButtonElement>(null)
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const shouldShowImageGenSource = useFeatureFlag('actions_custom_images_show_image_gen_source')
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const shouldShowImageGenJob = useFeatureFlag('actions_custom_images_show_image_gen_job')

  function openDeleteDialog() {
    setDeleteDialogIsOpen(true)
  }

  function closeDeleteDialog() {
    setDeleteDialogIsOpen(false)
    contextMenuButtonRef.current?.focus()
  }

  function handleDeleteDialogSuccess() {
    setImageVersionState(ImageVersionState.Deleting)
    setDeleteDialogIsOpen(false)
  }

  function handleDelete() {
    openDeleteDialog()
  }

  const size = version.size ?? 0

  const badges: Array<React.ReactElement<typeof ListItemTrailingBadge>> = []
  if (isLatest && imageVersionState !== ImageVersionState.Deleting) {
    badges.push(<ListItemTrailingBadge title="Latest" key={0} data-testid="latest-label" />)
  }
  if (version.enabled === false) {
    badges.push(<ListItemTrailingBadge title="Disabled" key={1} data-testid="disabled-label" />)
  }

  function getMappedImageType(type?: ImageSource) {
    if (type === ImageSource.Marketplace) return 'Partner'
    if (type === ImageSource.Curated) return 'GitHub'
    if (type === ImageSource.Custom) return 'Custom'
    return ''
  }

  function canDeleteImage() {
    return imageVersionState !== ImageVersionState.Deleting && props.canWriteCustomImages
  }

  const mappedImageType = getMappedImageType(version.sourceImageType)
  const sourceImageDetails =
    shouldShowImageGenSource && mappedImageType && version.sourceImageName && version.sourceImageVersion
      ? `Built from ${mappedImageType} image ${version.sourceImageName} (${version.sourceImageVersion})`
      : null

  return (
    <>
      <ListItem
        title={<ListItemTitle value={`Version ${version.version}`} trailingBadges={badges} />}
        metadata={
          <ListItemMetadata>
            <div className={styles.versionMetadata}>
              {!!version.lastUsedAt && (
                <span className="text-small color-fg-muted flex-shrink-0" data-testid="last-used-ago-text">
                  Last used {agoString(new Date(version.lastUsedAt))}
                </span>
              )}
              <ImageStateIndicator imageState={imageVersionState} />
            </div>
            {shouldShowImageGenJob ? (
              <ActionMenu>
                <ActionMenu.Anchor>
                  {/* eslint-disable-next-line primer-react/a11y-remove-disable-tooltip */}
                  <IconButton
                    aria-label={`Actions: ${version.version}`}
                    title={`Actions: ${version.version}`}
                    icon={KebabHorizontalIcon}
                    variant="invisible"
                    unsafeDisableTooltip
                    ref={contextMenuButtonRef}
                    data-testid="kebab-menu-button"
                    className="ml-2"
                  />
                </ActionMenu.Anchor>
                <ActionMenu.Overlay>
                  <ActionList>
                    {version.checkRunUrl ? (
                      <ActionList.LinkItem href={version.checkRunUrl} target="_blank">
                        View job
                      </ActionList.LinkItem>
                    ) : (
                      <ActionList.Item disabled>View job</ActionList.Item>
                    )}
                    <ActionList.Item
                      variant={canDeleteImage() ? 'danger' : undefined}
                      disabled={!canDeleteImage()}
                      onSelect={handleDelete}
                    >
                      Delete image
                    </ActionList.Item>
                  </ActionList>
                </ActionMenu.Overlay>
              </ActionMenu>
            ) : (
              canDeleteImage() && (
                // eslint-disable-next-line primer-react/a11y-remove-disable-tooltip
                <IconButton
                  unsafeDisableTooltip
                  icon={TrashIcon}
                  aria-label="Delete"
                  variant="invisible"
                  onClick={handleDelete}
                  data-testid="trash-button"
                  className="ml-2"
                />
              )
            )}
          </ListItemMetadata>
        }
        className={styles.ListItem_0}
      >
        <ListItemMainContent>
          <ListItemDescription>
            <div>
              <span className="text-small color-fg-muted flex-shrink-0" data-testid="version-description">
                {size} GB created {<RelativeTime date={new Date(version.createdAt)} />}
                <br />
              </span>

              {shouldShowImageGenSource && sourceImageDetails && (
                <div className="text-small color-fg-muted flex-shrink-0" data-testid="image-generation-source">
                  <Truncate title={sourceImageDetails} maxWidth={610}>
                    {sourceImageDetails}
                  </Truncate>
                </div>
              )}

              {version.stateDetails && (
                <div className="text-small color-fg-muted flex-shrink-0" data-testid="state-details">
                  <Truncate title={version.stateDetails} maxWidth={210}>
                    {version.stateDetails}
                  </Truncate>
                </div>
              )}
            </div>
          </ListItemDescription>
        </ListItemMainContent>
      </ListItem>
      {deleteDialogIsOpen && (
        <DeleteCustomImageVersionDialog
          imageDefinitionId={imageDefinitionId}
          version={version.version}
          entityLogin={entityLogin}
          isEnterprise={isEnterprise}
          onCancel={closeDeleteDialog}
          onDismiss={closeDeleteDialog}
          onSuccess={handleDeleteDialogSuccess}
        />
      )}
    </>
  )
}
